                this.targetFloor = this.currentFloor;
                this.state = STATE.DOOR_OPENING;
                this.doorTimer = 0;
                return;
            }
            this.direction = 0;
            this.targetFloor = null;
            this.state = STATE.IDLE;
            this.servedThisDoorCycle = false;
