    wldAddNode(nodes, "hallE", 2.5, y, 0);
    wldAddNode(nodes, "hallNE", 2.5, y, -2.5);
    wldAddNode(nodes, "hallN", 0, y, -2.5);
    wldAddNode(nodes, "hallNW", -2.5, y, -2.5);
