// world.js - building geometry, per-floor layouts, furniture, navigation
// graph, call panels. Classic script: exposes window.WORLD / window.createWorld.

const WORLD = {
    FLOOR_HEIGHT: 3.4,
    FLOOR_COUNT: 6,
    BUILDING_WIDTH: 22,
    BUILDING_DEPTH: 18,
    SHAFT_WIDTH: 3,
    SHAFT_DEPTH: 3,
