    wldBox(g, 0.5, 0.5, 0.07, 0, 0.5, -0.24, mat);           // backrest (-Z)
    g.position.set(x, y, z);
    g.rotation.y = rotY;
    parent.add(g);
    return g;
}

function wldArmchair(parent, x, y, z, rotY, color) {
