    wldAddNode(nodes, "lobby_stand_NW", -6.5, y, -1.2);
    wldAddNode(nodes, "lobby_stand_midE", 8.5, y, 1.8);
    wldAddNode(nodes, "lobby_stand_midW", -8.5, y, 1.8);
