      const L = elevator.logic;
      const events = [];
      const origStep = L._tickStep.bind(L);
      let prevSt = L.state, prevFl = L.currentFloor;
      L._tickStep = function (dt) {
        origStep(dt);
        if (L.state === 'DOOR_OPEN' && (prevSt !== 'DOOR_OPEN' || prevFl !== L.currentFloor)) {
          events.push({ m: Math.round(Clock.simMinute*10)/10, openAt: L.currentFloor, dir: L.direction,
            pax: L.passengers.size, free: L.currentCapacityFree(), pB: L.pendingBoarders.size,
            dst: [...L.destinations].sort().join(''), dn: [...L.downCalls].sort().join(''),
            w1: agents.filter(a => a.state === 'WAITING_ELEVATOR' && a.currentFloor === L.currentFloor).length });
        }
        prevSt = L.state; prevFl = L.currentFloor;
        if (events.length >= 50) resolve(events);
      };
      setTimeout(() => resolve(events), 10000);
    });
  });
  console.log(out.map(e => JSON.stringify(e)).join('\n'));
  await browser.close();
})();
