const { chromium } = require('/Users/jeffgrover/Code/llm-eval/node_modules/playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', (err) => errors.push(err.message));
  await page.goto('file://' + process.cwd() + '/index.html');
  await page.waitForTimeout(2000);
  await page.evaluate(() => { Clock.timeScale = 240; Clock.simMinute = 10 * 60 + 30; });
  await page.waitForTimeout(8000);
  const rep = await page.evaluate(() => {
    const norm = (r) => ((r % (2*Math.PI)) + 2*Math.PI) % (2*Math.PI);
    let deskChecked = 0, deskOk = 0;
    const badDesk = [];
    agents.forEach(a => {
      if (a.role !== 'WORKER' || a.state !== 'AT_DESK' || !a.group || !a.group.userData.isSitting) return;
      deskChecked++;
      const ry = norm(a.group.rotation.y);
      if (Math.abs(ry - Math.PI) < 0.15) deskOk++;
      else badDesk.push(a.name + ':' + ry.toFixed(2));
    });
    // any seated agent: facing must match the sitTarget of the nearest waypoint on their floor
    let seatChecked = 0, seatOk = 0; const badSeat = [];
    agents.forEach(a => {
      if (!a.group || !a.group.userData.isSitting) return;
      const fl = world.floors[a.currentFloor];
      if (!fl) return;
      let bestWp = null, bestD = 0.35;
      for (const wp in fl.sitTargets) {
        if (!fl.sitTargets[wp].sit) continue;
        const p = fl.nodes[wp].pos;
        const d = Math.hypot(p.x - a.group.position.x, p.z - a.group.position.z);
        if (d < bestD) { bestD = d; bestWp = wp; }
      }
      if (!bestWp) return;
      seatChecked++;
      const want = norm(fl.sitTargets[bestWp].facing);
      const ry = norm(a.group.rotation.y);
      const diff = Math.abs(ry - want);
      if (diff < 0.15 || diff > 2*Math.PI - 0.15) seatOk++;
      else badSeat.push(a.name + '@' + bestWp + ' want' + want.toFixed(2) + ' got' + ry.toFixed(2));
    });
    // legs direction check: seated figure's knees must point along facing dir (local +Z rotated)
    return { time: Clock.format().trim(), deskChecked, deskOk, badDesk, seatChecked, seatOk, badSeat };
  });
  console.log(JSON.stringify(rep, null, 1));
  console.log('ERRORS:', errors.length ? errors.join('\n') : 'none');
  await browser.close();
})();
EOF
